    'entry with unparseable created_at must not appear in the output',
  );
});

test('parseTimelineJson skips an entry whose screen_name contains a markup-breaking character', () => {
  const tweets = parseTimelineJson(fixture);
  assert.ok(
    !tweets.some((t) => t.id === '1958000000000000006'),
    'a handle like "bad|handle" could break out of a Slack link construct and must be dropped, not throw',
  );
});

test('parseTimelineJson skips an entry whose rest_id is not purely numeric', () => {
  const tweets = parseTimelineJson(fixture);
  assert.ok(
    !tweets.some((t) => t.author === 'badid'),
    'a rest_id like "12a3" must be dropped, not throw',
  );
});

function tweetEntry(id, overrides = {}) {
  return {
    entryId: `tweet-${id}`,
    content: {
      entryType: 'TimelineTimelineItem',
      itemContent: {
        tweet_results: {
          result: {
            __typename: 'Tweet',
            rest_id: id,
            core: { user_results: { result: { core: { screen_name: 'somedev', name: 'Some Dev' } } } },
            legacy: {
              full_text: 'hey @entirehq',
              created_at: 'Tue Aug 18 14:02:11 +0000 2026',
              is_quote_status: false,
              in_reply_to_status_id_str: null,
              ...overrides,
            },
          },
        },
      },
    },
  };
}

test('parseTimelineJson dedupes a rest_id repeated across two TimelineAddEntries instructions', () => {
  const payload = {
    data: {
      search_by_raw_query: {
        search_timeline: {
          timeline: {
            instructions: [
              { type: 'TimelineAddEntries', entries: [tweetEntry('9990000000000000001')] },
              {
                type: 'TimelineAddEntries',
                entries: [tweetEntry('9990000000000000001'), tweetEntry('9990000000000000002')],
              },
            ],
          },
        },
      },
    },
  };

